/* called when gaining a level (before u.ulevel gets incremented);
   also called with u.ulevel==0 during hero initialization or for
   re-init if hero turns into a "new man/woman/elf/&c" */
/**
 * @returns {number} int
 */
export function newhp() {   // attrib.c:1080
    let hp = 0, conplus = 0;
    if (u.ulevel === 0) {
        /* Initialize hit points */
        hp = gu.urole.hpadv.infix + gu.urace.hpadv.infix;
        if (gu.urole.hpadv.inrnd > 0) {
            hp = hp + rnd(gu.urole.hpadv.inrnd) | 0;
        }
        if (gu.urace.hpadv.inrnd > 0) {
            hp = hp + rnd(gu.urace.hpadv.inrnd) | 0;
        }
        if (svm.moves === 0) {
            /* initial hero; skip for polyself to new man */
            /* Initialize alignment stuff */
            u.ualign.type = aligns[flags.initalign].value;
            u.ualign.record = gu.urole.initrecord;
        }
        /* no Con adjustment for initial hit points */
    } else {
        if (u.ulevel < gu.urole.xlev) {
            hp = gu.urole.hpadv.lofix + gu.urace.hpadv.lofix;
            if (gu.urole.hpadv.lornd > 0) {
                hp = hp + rnd(gu.urole.hpadv.lornd) | 0;
            }
            if (gu.urace.hpadv.lornd > 0) {
                hp = hp + rnd(gu.urace.hpadv.lornd) | 0;
            }
        } else {
            hp = gu.urole.hpadv.hifix + gu.urace.hpadv.hifix;
            if (gu.urole.hpadv.hirnd > 0) {
                hp = hp + rnd(gu.urole.hpadv.hirnd) | 0;
            }
            if (gu.urace.hpadv.hirnd > 0) {
                hp = hp + rnd(gu.urace.hpadv.hirnd) | 0;
            }
        }
        if (ACURR(A.CON) <= 3) {
            conplus = -2;
        } else if (ACURR(A.CON) <= 6) {
            conplus = -1;
        } else if (ACURR(A.CON) <= 14) {
            conplus = 0;
        } else if (ACURR(A.CON) <= 16) {
            conplus = 1;
        } else if (ACURR(A.CON) === 17) {
            conplus = 2;
        } else if (ACURR(A.CON) === 18) {
            conplus = 3;
        } else {
            conplus = 4;
        }
        hp = hp + conplus | 0;
    }
    if (hp <= 0) {
        hp = 1;
    }
    if (u.ulevel < MAXULEV) {
        /* remember increment; future level drain could take it away again */
        u.uhpinc[u.ulevel] = $c.i16(hp);
    } else {
        /* after level 30, throttle hit point gains from extra experience;
           once max reaches 1200, further increments will be just 1 more */
        let lim = $c.i8(5 - $c.div32(u.uhpmax, 300) | 0);
        lim = max(lim, 1);
        if (hp > lim) {
            hp = lim;
        }
    }
    return hp;
}
